//! PostScript glyph names as FreeType 2.15.0 reads them (`psnames`): the
//! Unicode value of a name, through the Adobe Glyph List, and the Unicode
//! charmap FreeType builds from a CFF face's glyph names when the face has no
//! Unicode `cmap` subtable (`ps_unicodes_init`). Also the CFF standard strings
//! and predefined encodings and charsets.
//!
//! The tables are generated by `cargo xtask fonts tables` from FreeType's
//! `psnames/pstables.h` and `cff/cffload.c`.

#[rustfmt::skip] // Laid out by the generator.
mod tables;

use tables::{ADOBE_GLYPH_LIST, STANDARD_STRINGS};
pub(crate) use tables::{
    EXPERT_CHARSET, EXPERT_ENCODING, EXPERTSUBSET_CHARSET, ISOADOBE_CHARSET, STANDARD_ENCODING,
};
use triergon_core::{Budget, BudgetVec, Result};

/// Set in the Unicode value of a name with a suffix, such as `A.swash`.
const VARIANT_BIT: u32 = 0x8000_0000;

const fn base(unicode: u32) -> u32 {
    unicode & !VARIANT_BIT
}

/// The CFF standard string of `sid`, a glyph name.
pub(crate) fn standard_string(sid: u16) -> Option<&'static str> {
    STANDARD_STRINGS.get(usize::from(sid)).copied()
}

/// The glyphs FreeType adds a second mapping for (`ft_extra_glyph_unicodes`),
/// by name, when no glyph maps their code point otherwise.
const EXTRA_GLYPHS: [(&[u8], u32); 10] = [
    (b"Delta", 0x0394),
    (b"Omega", 0x03a9),
    (b"fraction", 0x2215),
    (b"hyphen", 0x00ad),
    (b"macron", 0x02c9),
    (b"mu", 0x03bc),
    (b"periodcentered", 0x2219),
    (b"space", 0x00a0),
    (b"Tcommaaccent", 0x021a),
    (b"tcommaaccent", 0x021b),
];

/// `ps_unicode_value`: the code point a glyph name stands for, with
/// [`VARIANT_BIT`] for a suffixed name; zero for none. `uniXXXX` takes exactly
/// four and `uXXXX` four to six upper-case hexadecimal digits; any other name
/// is looked up in the Adobe Glyph List up to its first `.`.
fn unicode_value(name: &[u8]) -> u32 {
    let at = |i: usize| name.get(i).copied().unwrap_or(0);
    let hex = |c: u8| match c {
        b'0'..=b'9' => Some(u32::from(c - b'0')),
        b'A'..=b'F' => Some(u32::from(c - b'A') + 10),
        _ => None,
    };
    // Up to `digits` digits from `start`; the value and where they stop.
    let digits = |start: usize, most: usize| {
        let mut value = 0;
        let mut end = start;
        while end - start < most {
            let Some(d) = hex(at(end)) else { break };
            value = (value << 4) + d;
            end += 1;
        }
        (value, end - start, at(end))
    };
    let suffixed = |value: u32, after: u8| match after {
        0 => Some(value),
        b'.' => Some(value | VARIANT_BIT),
        _ => None,
    };
    if name.starts_with(b"uni") {
        let (value, count, after) = digits(3, 4);
        if count == 4
            && let Some(value) = suffixed(value, after)
        {
            return value;
        }
    }
    if name.first() == Some(&b'u') {
        let (value, count, after) = digits(1, 6);
        if count >= 4
            && let Some(value) = suffixed(value, after)
        {
            return value;
        }
    }
    let stem = name.iter().position(|&c| c == b'.').unwrap_or(name.len());
    if stem == 0 {
        return 0;
    }
    let value = adobe_glyph_index(&name[..stem]);
    if stem < name.len() {
        value | VARIANT_BIT
    } else {
        value
    }
}

/// `ft_get_adobe_glyph_index`: the code point of `name` in FreeType's
/// compressed Adobe Glyph List, zero for none.
fn adobe_glyph_index(name: &[u8]) -> u32 {
    let list = &ADOBE_GLYPH_LIST;
    let byte = |i: usize| list.get(i).copied().map_or(0, usize::from);
    let word = |i: usize| byte(i) << 8 | byte(i + 1);
    // A name byte from 128 matches no letter of the list, which stores seven
    // bits, whether C's `char` is signed (x86) or unsigned (ARM).
    let letter = |c: u8| i32::from(c);
    let Some((&first, mut rest)) = name.split_first() else {
        return 0;
    };
    let count = byte(1);
    let (mut min, mut max) = (0, count);
    let mut p = None;
    while min < max {
        let mid = (min + max) >> 1;
        let q = word(2 + mid * 2);
        let c2 = (byte(q) & 127) as i32;
        if c2 == letter(first) {
            p = Some(q);
            break;
        }
        if c2 < letter(first) {
            min = mid + 1;
        } else {
            max = mid;
        }
    }
    let Some(mut p) = p else { return 0 };
    loop {
        let Some((&c, after)) = rest.split_first() else {
            return if byte(p) & 128 == 0 && byte(p + 1) & 128 != 0 {
                word(p + 2) as u32
            } else {
                0
            };
        };
        rest = after;
        let c = letter(c);
        if byte(p) & 128 != 0 {
            p += 1;
            if c != (byte(p) & 127) as i32 {
                return 0;
            }
            continue;
        }
        p += 1;
        let mut count = byte(p) & 127;
        if byte(p) & 128 != 0 {
            p += 2;
        }
        p += 1;
        let mut next = None;
        while count > 0 {
            let q = word(p);
            if c == (byte(q) & 127) as i32 {
                next = Some(q);
                break;
            }
            count -= 1;
            p += 2;
        }
        match next {
            Some(q) => p = q,
            None => return 0,
        }
    }
}

/// The Unicode charmap FreeType builds from glyph names (`PS_Unicodes`):
/// (Unicode value with [`VARIANT_BIT`], glyph) pairs sorted by base code
/// point, a base name before its variants, glyphs in index order otherwise,
/// as glibc's stable `qsort` leaves them.
#[derive(Debug)]
pub(crate) struct UnicodeMap {
    maps: BudgetVec<(u32, u16)>,
}

impl UnicodeMap {
    /// `ps_unicodes_init` over the glyph names in index order (`None` for a
    /// glyph without one). `None` when no name maps to a code point, where
    /// FreeType makes no charmap (`No_Unicode_Glyph_Name`).
    pub(crate) fn new<'n>(
        names: impl Iterator<Item = Option<&'n [u8]>>,
        budget: &Budget,
    ) -> Result<Option<Self>> {
        let mut maps = BudgetVec::new(budget);
        // Per extra glyph: unseen, a candidate glyph, or mapped otherwise.
        let mut extra: [Option<Option<u16>>; EXTRA_GLYPHS.len()] = [Some(None); EXTRA_GLYPHS.len()];
        for (glyph, name) in names.enumerate() {
            let Some(name) = name.filter(|n| !n.is_empty()) else {
                continue;
            };
            let glyph = u16::try_from(glyph).unwrap_or(u16::MAX);
            if let Some(n) = EXTRA_GLYPHS.iter().position(|&(extra, _)| extra == name)
                && extra[n] == Some(None)
            {
                extra[n] = Some(Some(glyph));
            }
            let unicode = unicode_value(name);
            if base(unicode) != 0 {
                if let Some(n) = EXTRA_GLYPHS.iter().position(|&(_, u)| u == unicode) {
                    extra[n] = None;
                }
                maps.try_push((unicode, glyph)).map_err(|e| e.error)?;
            }
        }
        for (n, state) in extra.into_iter().enumerate() {
            if let Some(Some(glyph)) = state {
                maps.try_push((EXTRA_GLYPHS[n].1, glyph))
                    .map_err(|e| e.error)?;
            }
        }
        if maps.is_empty() {
            return Ok(None);
        }
        maps.as_mut_slice()
            .sort_by_key(|&(unicode, _)| (base(unicode), unicode));
        Ok(Some(Self { maps }))
    }

    /// `ps_unicodes_char_index`: the glyph of `code`, zero for none. Its binary
    /// search predicts the next probe by the distance in code points, with the
    /// pointer arithmetic of the target: a probe below the one before wraps
    /// out of range on a 64-bit target and moves back on a 32-bit one. Where
    /// names repeat a code point, the probes decide which glyph is found.
    pub(crate) fn char_index(&self, code: u32) -> u16 {
        self.char_index_for(code, PointerWidth::TARGET)
    }

    /// [`Self::char_index`] with FreeType's probes on a target of `width`.
    fn char_index_for(&self, code: u32, width: PointerWidth) -> u16 {
        let maps = self.maps.as_slice();
        let (mut min, mut max) = (0_usize, maps.len());
        let mut mid = (max - min) >> 1;
        let mut result = None;
        while min < max {
            let (unicode, glyph) = maps[mid];
            if unicode == code {
                result = Some(glyph);
                break;
            }
            let base = base(unicode);
            if base == code {
                // A variant: remembered while the search goes on for the base.
                result = Some(glyph);
            }
            if base < code {
                min = mid + 1;
            } else {
                max = mid;
            }
            let next = width.predicted(mid, code.wrapping_sub(base));
            mid = match next {
                Some(next) if (min..max).contains(&next) => next,
                _ => min + ((max - min) >> 1),
            };
        }
        result.unwrap_or(0)
    }

    /// `ps_unicodes_char_next`: the first code point after `code` the map
    /// gives a glyph, and that glyph; a variant of `code + 1` counts.
    /// `(0, 0)` past the last. Its probes use 32-bit unsigned arithmetic on
    /// every target.
    pub(crate) fn char_next(&self, code: u32) -> (u32, u16) {
        let maps = self.maps.as_slice();
        let len = u32::try_from(maps.len()).unwrap_or(u32::MAX);
        let code = code.wrapping_add(1);
        let (mut min, mut max) = (0_u32, len);
        let mut mid = (max - min) >> 1;
        let mut result = None;
        while min < max {
            let (unicode, glyph) = maps[mid as usize];
            if unicode == code {
                return (code, glyph);
            }
            let base = base(unicode);
            if base == code {
                result = Some(glyph);
            }
            if base < code {
                min = mid + 1;
            } else {
                max = mid;
            }
            mid = mid.wrapping_add(code.wrapping_sub(base));
            if mid >= max || mid < min {
                mid = min + (max - min) / 2;
            }
        }
        if let Some(glyph) = result {
            return (code, glyph);
        }
        match maps.get(min as usize) {
            Some(&(unicode, glyph)) => (base(unicode), glyph),
            None => (0, 0),
        }
    }
}

/// The pointer width FreeType's `ps_unicodes_char_index` runs with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PointerWidth {
    Bits32,
    Bits64,
}

impl PointerWidth {
    const TARGET: Self = if cfg!(target_pointer_width = "32") {
        Self::Bits32
    } else {
        Self::Bits64
    };

    /// `mid += distance` on a `PS_UniMap*` (eight bytes): the index it
    /// points at, `None` where the pointer leaves every index. On a 32-bit
    /// target the byte offset wraps at 2^32, so a distance from a negative
    /// difference moves back; on a 64-bit one it moves far past the end.
    fn predicted(self, mid: usize, distance: u32) -> Option<usize> {
        match self {
            Self::Bits32 => {
                let step = (distance.wrapping_mul(8).cast_signed() >> 3) as isize;
                mid.checked_add_signed(step)
            }
            Self::Bits64 => mid.checked_add(distance as usize),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{
        PointerWidth, UnicodeMap, VARIANT_BIT, adobe_glyph_index, standard_string, unicode_value,
    };
    use triergon_core::Budget;

    #[test]
    fn names_read_as_freetype_reads_them() {
        assert_eq!(unicode_value(b"A"), 0x41);
        assert_eq!(unicode_value(b"A.swash"), 0x41 | VARIANT_BIT);
        assert_eq!(unicode_value(b"uni00E9"), 0xe9);
        assert_eq!(
            unicode_value(b"uni00e9"),
            0,
            "lower-case digits are not hexadecimal"
        );
        assert_eq!(unicode_value(b"u1F600"), 0x1_f600);
        assert_eq!(unicode_value(b"u1F600.alt"), 0x1_f600 | VARIANT_BIT);
        assert_eq!(
            unicode_value(b"uni0041x"),
            0,
            "a name that is neither is looked up"
        );
        assert_eq!(unicode_value(b".notdef"), 0);
        assert_eq!(unicode_value(b"Delta"), 0x2206);
        assert_eq!(adobe_glyph_index(b"zzz"), 0);
        assert_eq!(adobe_glyph_index(b"ff"), 0xfb00);
        assert_eq!(standard_string(34), Some("A"));
        assert_eq!(standard_string(391), None);
    }

    #[test]
    fn the_map_sorts_variants_after_bases_and_adds_extra_glyphs() {
        let budget = Budget::new(1 << 16).unwrap();
        let names: [Option<&[u8]>; 6] = [
            Some(b".notdef"),
            Some(b"A.swash"),
            Some(b"A"),
            None,
            Some(b"space"),
            Some(b"Delta"),
        ];
        let map = UnicodeMap::new(names.into_iter(), &budget)
            .unwrap()
            .unwrap();
        assert_eq!(map.char_index(0x41), 2);
        assert_eq!(map.char_index(0xa0), 4, "space also maps U+00A0");
        assert_eq!(map.char_index(0x394), 5, "Delta also maps U+0394");
        assert_eq!(map.char_index(0x42), 0);
        assert_eq!(map.char_next(0), (0x20, 4));
        assert_eq!(map.char_next(0x20), (0x41, 2));
        assert_eq!(map.char_next(0x2206), (0, 0));
        let none: [Option<&[u8]>; 2] = [Some(b".notdef"), Some(b"glyph1")];
        assert!(
            UnicodeMap::new(none.into_iter(), &budget)
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn duplicate_names_find_the_glyph_the_target_width_probes() {
        // Four glyphs named A, then B to E: a search for A first probes B,
        // below which a 32-bit target steps back one entry and a 64-bit one
        // restarts at the middle of what is left.
        let budget = Budget::new(1 << 16).unwrap();
        let names: [Option<&[u8]>; 9] = [
            Some(b".notdef"),
            Some(b"A"),
            Some(b"A"),
            Some(b"A"),
            Some(b"A"),
            Some(b"B"),
            Some(b"C"),
            Some(b"D"),
            Some(b"E"),
        ];
        let map = UnicodeMap::new(names.into_iter(), &budget)
            .unwrap()
            .unwrap();
        assert_eq!(map.char_index_for(0x41, PointerWidth::Bits32), 4);
        assert_eq!(map.char_index_for(0x41, PointerWidth::Bits64), 3);
        assert_eq!(map.char_index_for(0x42, PointerWidth::Bits32), 5);
        assert_eq!(map.char_index_for(0x42, PointerWidth::Bits64), 5);
    }
}
